import { axiosPlus, type AxiosConfig } from '@/api/config';

type AskConfig = AxiosConfig<'/api/v1/admin/ai/chat/ask', 'post'>;
type ModelsConfig = AxiosConfig<'/api/v1/admin/ai/chat/models', 'post'>;
export type ChatRequest = NonNullable<AskConfig['data']>;

/** Chat descriptor keys are opaque and generated by the server. */
export const modelsFn = (config?: Omit<ModelsConfig, 'url' | 'method'>) =>
  axiosPlus({ url: '/api/v1/admin/ai/chat/models', method: 'post', data: {}, ...config });

export const askFn = (config: Omit<AskConfig, 'url' | 'method'>) =>
  axiosPlus({ url: '/api/v1/admin/ai/chat/ask', method: 'post', ...config });
